      "code": "void UExtractionCombatComponent::RequestShot(const FVector& Target)\n{\n\tRefreshMechanics();\n\tauto* C = Character();\n\tauto* W = C ? C->GetEquippedWeapon() : nullptr;\n\tif (!CanAct() || !CanFireMechanics() || C->Melee->Active || !Cast<AHitScanWeapon>(W)) return;\n\tif (C->GetExtractionInteraction()->InventoryOpen) return;\n\tif (!W->IsEmpty() && C->GetCombatState() == ECombatState::ECS_Unoccuiped)\n\t\tC->GetCombat()->NotifyLocalShot();\n\tconst uint32 Id = ++LocalShotId;\n\tSprintFire.PendingShot = false;\n\tfloat ViewTime = -1.f;\n\tif (!C->HasAuthority())\n\t{\n\t\tPendingShots.Add(Id, W);\n\t\tC->GetCombat()->LocalFire(ResolveShot(Target, Id, true));\n\t\t// 远端角色在本机画面上约落后服务器单程延迟，这就是开枪时看到的那一刻。\n\t\tif (auto* PC = Cast<ABrokenEdgePlayerController>(C->GetController()))\n\t\t\tViewTime = PC->GetServerTime() - PC->SingleTripTime;\n\t}\n\tServerRequestShot(Id, W, Target, ViewTime);\n}"
